'use strict';
const $=s=>document.querySelector(s);
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('ttkz-'+k))??f}catch{return f}};
const state={city:'All cities',facility:'All halls',date:localDate(),level:'All levels',profile:read('profile',{name:'Alex',city:'Almaty',level:'Intermediate',bio:'Always up for a friendly game.',preference:'Weekday evenings'}),bookings:read('bookings',[]),favorites:read('favorites',[]),requests:read('requests',[])};
function localDate(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function save(k,v){try{localStorage.setItem('ttkz-'+k,JSON.stringify(v));return true}catch{toast('Browser storage is unavailable. Changes last for this visit.');return false}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const halls=[{id:1,name:'Spin Arena',city:'Almaty',address:'Abay Avenue, demo location',price:2500,rating:'4.9',tables:8,tags:['Professional tables','Changing rooms','Parking'],badge:'Community favorite',tone:'#636d59'},{id:2,name:'Topspin Club',city:'Astana',address:'Turan Avenue, demo location',price:3000,rating:'4.8',tables:6,tags:['Professional tables','Equipment rental','Parking'],badge:'Great for all levels',tone:'#7d8e91'},{id:3,name:'Dostyk Table Tennis',city:'Almaty',address:'Dostyk Avenue, demo location',price:2000,rating:'4.7',tables:4,tags:['Equipment rental','Changing rooms','Coaching'],badge:'Beginner friendly',tone:'#99755d'},{id:4,name:'Shymkent Ping Pong',city:'Shymkent',address:'Tauke Khan Avenue, demo location',price:1800,rating:'4.8',tables:5,tags:['Equipment rental','Coaching','Parking'],badge:'New to the community',tone:'#77866c'},{id:5,name:'Saryarka TT Center',city:'Astana',address:'Saryarka Avenue, demo location',price:2500,rating:'4.6',tables:6,tags:['Professional tables','Changing rooms','Coaching'],badge:'Train your way',tone:'#6b7884'},{id:6,name:'Karaganda Spin Club',city:'Karaganda',address:'Bukhar Zhyrau Avenue, demo location',price:1500,rating:'4.7',tables:4,tags:['Equipment rental','Parking','Coaching'],badge:'Local favorite',tone:'#8c816c'}];
const players=[{id:1,name:'Aigerim S.',city:'Almaty',level:'Intermediate',bio:'Looking for a regular practice partner. Let’s improve our rallies together.',time:'Weekday evenings',color:'#e2d9c4'},{id:2,name:'Dias K.',city:'Astana',level:'Advanced',bio:'Competitive player who enjoys match practice and meeting new opponents.',time:'Weekend mornings',color:'#cbdde0'},{id:3,name:'Madina A.',city:'Almaty',level:'Beginner',bio:'New to table tennis! Happy to meet other beginners for a friendly game.',time:'Weekend afternoons',color:'#e4cfc6'},{id:4,name:'Arman T.',city:'Shymkent',level:'Intermediate',bio:'A good rally and a little friendly competition make the perfect evening.',time:'Weekday evenings',color:'#d4dfbc'}];
const tournaments=[{id:1,name:'Almaty Autumn Open',city:'Almaty',day:'14',month:'NOV',date:'14 November 2026',level:'All levels',venue:'Spin Arena',description:'A friendly singles tournament bringing the local community together. Group stages followed by knockout matches.'},{id:2,name:'Capital City Championship',city:'Astana',day:'21',month:'NOV',date:'21 November 2026',level:'Intermediate & advanced',venue:'Topspin Club',description:'A full day of competitive singles matches for experienced players. Warm-up tables and spectator seating available.'},{id:3,name:'First Serve: Beginners Cup',city:'Shymkent',day:'05',month:'DEC',date:'5 December 2026',level:'Beginners',venue:'Shymkent Ping Pong',description:'Your first tournament starts here. A relaxed round-robin format with friendly guidance for new players.'}];
function room(h,hero=false){return `<svg viewBox="0 0 600 340" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Illustration of a table tennis hall"><defs><linearGradient id="floor${h.id}" x2="0" y2="1"><stop stop-color="${h.tone}"/><stop offset="1" stop-color="#b4ae91"/></linearGradient></defs><rect width="600" height="340" fill="${h.tone}"/><path d="M0 0H600V190H0Z" fill="#d9ded0"/><path d="M0 0L90 45V190L0 240Z" fill="#a9b29e"/><path d="M600 0L510 45V190L600 240Z" fill="#bac3ae"/><path d="M0 190H600V340H0Z" fill="url(#floor${h.id})"/><path d="M90 0V190M250 0V190M420 0V190M510 0V190" stroke="#bdc7b4" stroke-width="5"/><path d="M0 35L600 35M0 90L600 90" stroke="#b7c1ad" stroke-width="3"/><path d="M117 56H216V137H117ZM279 56H378V137H279ZM442 56H500V137H442Z" fill="#eef1df"/><path d="M125 60V132M169 60V132M287 60V132M330 60V132M450 60V132" stroke="#d4dfc6" stroke-width="4"/><path d="M0 270L600 230M180 340L285 190M500 340L400 190" stroke="#d5d2ba" opacity=".3"/><g transform="${hero?'translate(-10,-10) scale(1.13)':'translate(0,0)'}"><path d="M171 220L162 290M387 220L399 290M232 172L231 230M423 172L437 234" stroke="#21372d" stroke-width="9"/><path d="M141 221L223 158H438L384 221Z" fill="#206449" stroke="#d9e6c3" stroke-width="3"/><path d="M141 221V231H384V221M384 221L438 158V168L384 231" fill="#154731"/><path d="M180 191H411M330 158L267 221" stroke="#e3eccd" stroke-width="2"/><path d="M176 175L413 175V196L176 196Z" fill="#e9eedb" fill-opacity=".5" stroke="#eef3db" stroke-width="2"/><path d="M183 177V195M191 177V195M199 177V195M207 177V195M215 177V195M223 177V195M231 177V195M239 177V195M247 177V195M255 177V195M263 177V195M271 177V195M279 177V195M287 177V195M295 177V195M303 177V195M311 177V195M319 177V195M327 177V195M335 177V195M343 177V195M351 177V195M359 177V195M367 177V195M375 177V195M383 177V195M391 177V195M399 177V195M407 177V195M176 182H413M176 188H413" stroke="#c4d1b3" stroke-width=".7"/><circle cx="338" cy="205" r="4" fill="#f7f5df"/></g><path d="M21 24H100M492 24H570" stroke="#fffde8" stroke-width="6"/>${hero?'<circle cx="509" cy="284" r="34" fill="#ddedac"/><path d="M489 306L473 329" stroke="#dac2a2" stroke-width="12"/><circle cx="542" cy="243" r="8" fill="#f6f5df"/>':''}</svg>`}
function nav(){let page=location.hash.slice(1)||'halls';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));$('#profileName').textContent=state.profile.name;$('.avatar.small').textContent=state.profile.name.charAt(0).toUpperCase();if(page==='players')renderPlayers();else if(page==='tournaments')renderTournaments();else if(page==='bookings')renderBookings();else if(page==='profile')renderProfile();else renderHalls()}
function cities(selected,all=true){return (all?['All cities','Almaty','Astana','Shymkent','Karaganda']:['Almaty','Astana','Shymkent','Karaganda']).map(x=>`<option ${x===selected?'selected':''}>${x}</option>`).join('')}
function renderHalls(){let list=halls.filter(h=>(state.city==='All cities'||h.city===state.city)&&(state.facility==='All halls'||state.facility==='Favorites'&&state.favorites.includes(h.id)||h.tags.includes(state.facility)));$('#app').innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">Your game. Your community.</div><h1>Good games start<br>with <em>a great place.</em></h1><p>Find a table, meet your next playing partner, and be part of Kazakhstan’s table tennis community.</p><div class="community-proof"><div class="mini-avatars"><span>AK</span><span>DS</span><span>MA</span><span>+</span></div><span>Built for <b>every level</b>, from first serve to match point</span></div></div><div class="hero-art">${room({id:0,tone:'#78876b'},true)}<span class="art-tag">A little practice. A lot of possibility.</span><span class="art-note">YOUR NEXT GAME IS CLOSER THAN YOU THINK ↗</span></div></section><form class="search-panel" id="searchForm"><div class="field"><label for="city">⌖ &nbsp; WHERE DO YOU WANT TO PLAY?</label><select id="city">${cities(state.city)}</select></div><div class="field"><label for="searchDate">▦ &nbsp; CHOOSE A DATE</label><input id="searchDate" type="date" min="${localDate()}" value="${state.date}" required></div><div class="field"><label for="searchTime">◷ &nbsp; PREFERRED TIME</label><select id="searchTime"><option value="">Any time</option><option value="morning">Morning · 09:00–12:00</option><option value="afternoon">Afternoon · 12:00–17:00</option><option value="evening">Evening · 17:00–21:00</option></select></div><button class="btn">Find a table <span>↗</span></button></form><div class="section-title"><div><h2>Find your place to play</h2><p>Good tables. Welcoming spaces. Your kind of game.</p></div><button class="text-button" id="myBookings">My bookings ↗</button></div><div class="filter-row"><div class="chips">${['All halls','Professional tables','Equipment rental','Coaching','Favorites'].map(t=>`<button class="chip ${state.facility===t?'active':''}" data-filter="${t}">${t==='Favorites'?'♡ ':''}${t}</button>`).join('')}</div><span class="result-count">${list.length} halls to explore</span></div><section class="cards" aria-label="Sports halls">${list.length?list.map(h=>`<article class="hall-card"><div class="venue-image">${room(h)}<span class="badge">${h.badge}</span><button class="heart" data-favorite="${h.id}" aria-label="${state.favorites.includes(h.id)?'Remove':'Add'} ${h.name} ${state.favorites.includes(h.id)?'from':'to'} favorites" aria-pressed="${state.favorites.includes(h.id)}">${state.favorites.includes(h.id)?'♥':'♡'}</button></div><div class="card-body"><div class="card-top"><h3>${h.name}</h3><span class="rating"><b>★</b> ${h.rating} <span style="color:#8a9185">· demo</span></span></div><div class="location">⌖ ${h.city} · ${h.tables} tables</div><div class="facilities">${h.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="card-bottom"><span class="price">${h.price.toLocaleString()} ₸ <small>/ hour</small></span><button class="btn secondary" data-book="${h.id}">View & book ↗</button></div></div></article>`).join(''):'<div class="empty"><h3>No halls found</h3><p>Try another city or choose a different filter.</p><button class="btn secondary" id="resetFilters">Reset filters</button></div>'}</section><div class="lower-grid"><section class="promo"><div class="eyebrow">Better together</div><h3 style="margin-top:10px">Your next rival. Your new friend.</h3><p>Find someone at your level and turn “sometime” into your next game.</p><a class="text-button" href="#players">Find a playing partner ↗</a><span class="promo-art">◎</span></section><section class="promo dark"><div class="eyebrow">A little friendly competition</div><h3 style="margin-top:10px">Bring your game to the table.</h3><p>Discover local tournaments and find your next challenge.</p><a class="text-button" href="#tournaments">Explore tournaments ↗</a><span class="promo-art">♜</span></section></div><p class="demo-note">CONCEPT PREVIEW · All venues, prices, ratings, players, and events are illustrative. Bookings are saved in this browser only.</p>`;
$('#searchTime').value=state.time||'';$('#searchForm').onsubmit=e=>{e.preventDefault();state.city=$('#city').value;state.date=$('#searchDate').value;state.time=$('#searchTime').value;renderHalls();$('.section-title').scrollIntoView({behavior:'smooth',block:'start'});toast('Showing halls for your selected date. Choose a hall to check times.')};$('#myBookings').onclick=()=>location.hash='bookings';document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.facility=b.dataset.filter;renderHalls()});document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{let id=+b.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save('favorites',state.favorites);renderHalls()});document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>bookingModal(+b.dataset.book));if($('#resetFilters'))$('#resetFilters').onclick=()=>{state.city='All cities';state.facility='All halls';renderHalls()}}
function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
function formatDate(d){return new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}
function occupied(hall,table,date,hour){return state.bookings.some(b=>b.hall===hall&&b.table===table&&b.date===date&&b.hour===hour)||((hall+table+Number(date.slice(-2)))%4===0&&[12,18].includes(hour))}
function pastSlot(date,hour){return new Date(`${date}T${String(hour).padStart(2,'0')}:00:00`)<=new Date()}
function bookingModal(id){const h=halls.find(x=>x.id===id);let selected=null;modal(`<div class="eyebrow">Find your next game</div><h2>${h.name}</h2><p>⌖ ${h.city} · ${h.address}</p><div class="facilities" style="margin-top:14px">${h.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="form-grid"><div class="field"><label for="bookDate">Date</label><input type="date" id="bookDate" min="${localDate()}" value="${state.date}"></div><div class="field"><label for="table">Table</label><select id="table">${Array.from({length:h.tables},(_,i)=>`<option value="${i+1}">Table ${i+1}</option>`).join('')}</select></div></div><p>Choose a one-hour session</p><div class="slots" id="slots"></div><div id="bookingSummary" class="summary">Select an available time to continue.</div><button id="confirmBook" class="btn wide" disabled>Confirm demo booking ↗</button><p class="demo-note">Demo reservation · No payment or real venue reservation. Unavailable times include sample reservations. Conflict prevention works within this browser only.</p>`);function slots(){selected=null;$('#confirmBook').disabled=true;$('#bookingSummary').textContent='Select an available time to continue.';const date=$('#bookDate').value,table=+$('#table').value;if(!date||date<localDate()){$('#slots').innerHTML='<p>Please choose today or a future date.</p>';return}let hours=Array.from({length:12},(_,i)=>i+9).filter(t=>!state.time||state.time==='morning'&&t<12||state.time==='afternoon'&&t>=12&&t<17||state.time==='evening'&&t>=17);$('#slots').innerHTML=hours.map(t=>`<button class="slot" data-hour="${t}" ${occupied(id,table,date,t)||pastSlot(date,t)?'disabled':''} aria-pressed="false">${String(t).padStart(2,'0')}:00</button>`).join('');document.querySelectorAll('[data-hour]').forEach(b=>b.onclick=()=>{selected=+b.dataset.hour;document.querySelectorAll('[data-hour]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});$('#bookingSummary').innerHTML=`${esc(h.name)} · Table ${table}<br>${formatDate(date)} · ${selected}:00–${selected+1}:00<br><strong>Total: ${h.price.toLocaleString()} ₸</strong> · 1 hour`;$('#confirmBook').disabled=false})}$('#bookDate').onchange=slots;$('#table').onchange=slots;slots();$('#confirmBook').onclick=()=>{let date=$('#bookDate').value,table=+$('#table').value;if(selected===null||!date||date<localDate()||pastSlot(date,selected))return;state.bookings=read('bookings',state.bookings);if(occupied(id,table,date,selected)){toast('This slot is already booked. Please choose another.');slots();return}state.bookings.push({id:crypto.randomUUID(),hall:id,table,date,hour:selected});save('bookings',state.bookings);$('#modal').close();toast('Demo booking confirmed. Your next game is on!');location.hash='bookings'}}
function renderBookings(){$('#app').innerHTML=`<div class="page-head"><div class="eyebrow">Your time at the table</div><h1>My bookings</h1><p>Your next game, all in one place.</p></div><div class="notice">Demo bookings are stored on this device. They do not reserve a real table.</div>${state.bookings.length?state.bookings.slice().sort((a,b)=>a.date.localeCompare(b.date)||a.hour-b.hour).map(b=>{let h=halls.find(x=>x.id===b.hall);return `<article class="booking-row"><div><h3>${h.name} <span class="level">${pastSlot(b.date,b.hour)?'Past session':'Confirmed · demo'}</span></h3><p>${h.city} · Table ${b.table} · ${formatDate(b.date)} · ${b.hour}:00–${b.hour+1}:00</p><p>${h.price.toLocaleString()} ₸ · 1 hour</p></div><button class="btn secondary" data-cancel="${b.id}">Cancel booking</button></article>`}).join(''):'<div class="empty"><h3>Your next game is waiting</h3><p>You haven’t booked a table yet. Explore halls and pick your time.</p><a class="btn" href="#halls">Find a hall ↗</a></div>'}`;document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{modal(`<h2>Cancel this booking?</h2><p>The time slot will become available again in this demo.</p><button class="btn wide" id="cancelConfirm" style="margin-top:25px">Yes, cancel booking</button>`);$('#cancelConfirm').onclick=()=>{state.bookings=state.bookings.filter(x=>x.id!==b.dataset.cancel);save('bookings',state.bookings);$('#modal').close();renderBookings();toast('Booking cancelled.')}})}
function renderPlayers(){$('#app').innerHTML=`<div class="page-head"><div class="eyebrow">Better together</div><h1>Find your kind of player.</h1><p>Practice a new serve, share a friendly rally, or find your next rival. There’s a partner for every game.</p></div><div class="notice">Sample player profiles · Invitations are simulated and saved only in this browser.</div><div class="search-panel" style="grid-template-columns:1fr 1fr"><div class="field"><label for="playerCity">City</label><select id="playerCity">${cities(state.playerCity||'All cities')}</select></div><div class="field"><label for="playerLevel">Playing level</label><select id="playerLevel">${['All levels','Beginner','Intermediate','Advanced'].map(t=>`<option ${state.level===t?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="section-title"><h2>Meet the community</h2><a class="text-button" href="#profile">Edit my profile ↗</a></div><div class="cards" id="playerCards"></div>`;function update(){let list=players.filter(p=>(!state.playerCity||state.playerCity==='All cities'||p.city===state.playerCity)&&(state.level==='All levels'||p.level===state.level));$('#playerCards').innerHTML=list.length?list.map(p=>`<article class="player-card"><div class="player-top"><span class="avatar" style="background:${p.color}">${p.name.split(' ').map(n=>n[0]).join('')}</span><div><h3>${p.name}</h3><p style="margin:5px 0 0">⌖ ${p.city}</p></div></div><span class="level">${p.level}</span><p>${p.bio}</p><div class="facilities"><span>◷ ${p.time}</span><span>Friendly practice</span></div><button class="btn secondary" data-invite="${p.id}" ${state.requests.includes(p.id)?'disabled':''}>${state.requests.includes(p.id)?'✓ Demo invitation sent':'Invite to play ↗'}</button></article>`).join(''):'<div class="empty"><h3>No players match yet</h3><p>Try another city or skill level.</p></div>';document.querySelectorAll('[data-invite]').forEach(b=>b.onclick=()=>{state.requests.push(+b.dataset.invite);save('requests',state.requests);update();toast('Demo invitation saved. No real message was sent.')})}$('#playerCity').onchange=()=>{state.playerCity=$('#playerCity').value;update()};$('#playerLevel').onchange=()=>{state.level=$('#playerLevel').value;update()};update()}
function renderTournaments(){$('#app').innerHTML=`<div class="page-head"><div class="eyebrow">Make every point count</div><h1>A little competition.<br>A lot of community.</h1><p>Discover your next challenge, cheer on local talent, and bring your game to the table.</p></div><div class="notice">Illustrative events for the diploma prototype. Dates and venues are not official announcements.</div><div class="section-title"><h2>Upcoming tournaments</h2><span class="result-count">3 sample events</span></div>${tournaments.map(t=>`<article class="tournament-card"><div class="date-box">${t.month}<b>${t.day}</b>2026</div><div><h3>${t.name}</h3><p style="font-size:12px">⌖ ${t.city} · ${t.venue}</p><span class="level" style="margin-top:8px">${t.level}</span></div><button class="btn secondary" data-event="${t.id}">Event details ↗</button></article>`).join('')}`;document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{let t=tournaments.find(x=>x.id===+b.dataset.event);modal(`<div class="eyebrow">Community tournament · sample</div><h2>${t.name}</h2><p>${t.description}</p><div class="summary"><strong>When</strong> · ${t.date}, 10:00<br><strong>Where</strong> · ${t.venue}, ${t.city}<br><strong>Who</strong> · ${t.level}<br><strong>Format</strong> · Singles</div><p>This is an illustrative announcement. Registration is not open in the conceptual prototype.</p><button class="btn wide" id="eventClose" style="margin-top:20px">Back to tournaments</button>`);$('#eventClose').onclick=()=>$('#modal').close()})}
function renderProfile(){const p=state.profile;$('#app').innerHTML=`<div class="page-head"><div class="eyebrow">A place in the community</div><h1>Your player profile.</h1><p>Let other players know a little about your game.</p></div><div class="profile-layout"><aside class="profile-aside"><span class="avatar">${esc(p.name[0].toUpperCase())}</span><h3>${esc(p.name)}</h3><span class="level">${esc(p.level)}</span><p style="margin-top:15px;font-size:12px">⌖ ${esc(p.city)}</p><a href="#bookings" class="btn secondary" style="margin-top:25px;font-size:12px">My bookings ↗</a></aside><form class="profile-form" id="profileForm"><div class="field"><label for="name">Display name</label><input id="name" value="${esc(p.name)}" required maxlength="40"></div><div class="form-grid"><div class="field"><label for="profileCity">City</label><select id="profileCity">${cities(p.city,false)}</select></div><div class="field"><label for="level">Playing level</label><select id="level">${['Beginner','Intermediate','Advanced'].map(t=>`<option ${p.level===t?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="field"><label for="preference">Preferred playing time</label><select id="preference">${['Weekday evenings','Weekday mornings','Weekend mornings','Weekend afternoons','Flexible'].map(t=>`<option ${p.preference===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="bio">About your game</label><textarea id="bio" rows="3" maxlength="240">${esc(p.bio)}</textarea></div><button class="btn">Save profile ↗</button><p>Your demo profile is saved in this browser. Account registration is planned for a future version.</p></form></div>`;$('#profileForm').onsubmit=e=>{e.preventDefault();const name=$('#name').value.trim();if(!name){$('#name').setCustomValidity('Please enter a display name.');$('#name').reportValidity();return}state.profile={name,city:$('#profileCity').value,level:$('#level').value,bio:$('#bio').value.trim(),preference:$('#preference').value};save('profile',state.profile);nav();toast('Your profile has been saved.')};$('#name').oninput=()=>$('#name').setCustomValidity('')}
let toastTimer;function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});$('#profileButton').onclick=()=>location.hash='profile';window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();nav();window.scrollTo({top:0,behavior:'smooth'})});window.addEventListener('storage',e=>{if(e.key==='ttkz-bookings')state.bookings=read('bookings',[])});nav();
